 31	  @Test
 32	  void guidedPublisherUsesOwnedBytesAndErasesBothBuffersAfterAckAndLostAck() throws Exception {
 33	    var contracts = new GuidedContracts();
 34	    var fixture =
 35	        contracts
 36	            .parse(
 37	                Files.readString(
 38	                    Path.of("../docs/specs/studio-observed-authoring/contracts/v3/fixtures.json")))
 39	            .path("documents");
 40	    ObjectNode dispatch = (ObjectNode) fixture.path("secretDispatch").deepCopy();
 41	    ObjectNode metadata = (ObjectNode) dispatch.remove("secret");
 42	    metadata.remove("value");
 43	    String canary = "GUIDED-BYTE-CANARY-" + java.util.UUID.randomUUID();
 44	    SSLContext tls = certificate();
 45	    var server = HttpsServer.create(new InetSocketAddress("localhost", 0), 0);
 46	    server.setHttpsConfigurator(new HttpsConfigurator(tls));
 47	    var received = new AtomicReference<byte[]>();
 48	    var status = new java.util.concurrent.atomic.AtomicInteger(200);
 49	    byte[] outcome = fixture.path("outcome").toString().getBytes(StandardCharsets.UTF_8);
 50	    server.createContext(
 51	        "/",
 52	        exchange -> {
 53	          byte[] body = exchange.getRequestBody().readAllBytes();
 54	          received.set(body);
 55	          exchange.sendResponseHeaders(status.get(), status.get() == 200 ? outcome.length : -1);
 56	          if (status.get() == 200) {
 57	            exchange.getResponseBody().write(outcome);
 58	          }
 59	          exchange.close();
 60	        });
 61	    server.start();
 62	    try {
 63	      var client =
 64	          new GuidedRunnerClient(
 65	              URI.create("https://localhost:" + server.getAddress().getPort()),
 66	              tls,
 67	              () -> "synthetic-controller-token",
 68	              contracts);
 69	      for (int reply : new int[] {200, 503}) {
 70	        status.set(reply);
 71	        var bytes = new AtomicReference<byte[]>();
 72	        client.observeRequestBytes(bytes::set);
 73	        char[] chars = canary.toCharArray();
 74	        var secret = new SecretValue(chars);
 75	        if (reply == 200) {
 76	          client.sendSecret(dispatch, metadata, secret);
 77	        } else {
 78	          assertThatThrownBy(() -> client.sendSecret(dispatch, metadata, secret))
 79	              .hasMessage("UNKNOWN_OUTCOME");
 80	        }
 81	        assertThat(new String(received.get(), StandardCharsets.UTF_8)).contains(canary);
 82	        assertThat(bytes.get()).containsOnly((byte) 0);
 83	        assertThat(chars).containsOnly('\0');
 84	        assertThat(dispatch.toString()).doesNotContain(canary);
 85	        assertThat(secret.toString()).isEqualTo("<secret>");
 86	        java.util.Arrays.fill(received.get(), (byte) 0);
 87	      }
 88	    } finally {
 89	      server.stop(0);
 90	      java.util.Arrays.fill(outcome, (byte) 0);
 91	    }
 92	  }
