112	  private void stalledResponse(int status, boolean interrupt, boolean defaultBound)
113	      throws Exception {
114	    var contracts = new GuidedContracts();
115	    var documents =
116	        contracts
117	            .parse(
118	                Files.readString(
119	                    Path.of("../docs/specs/studio-observed-authoring/contracts/v3/fixtures.json")))
120	            .path("documents");
121	    ObjectNode dispatch = (ObjectNode) documents.path("secretDispatch").deepCopy();
122	    ObjectNode metadata = (ObjectNode) dispatch.remove("secret");
123	    metadata.remove("value");
124	    String canary = "STALLED-BYTE-" + java.util.UUID.randomUUID();
125	    char[] chars = canary.toCharArray();
126	    var secret = new SecretValue(chars);
127	    var owned = new AtomicReference<byte[]>();
128	    var received = new AtomicReference<byte[]>();
129	    var requests = new java.util.concurrent.atomic.AtomicInteger();
130	    var headers = new java.util.concurrent.CountDownLatch(1);
131	    var disconnected = new java.util.concurrent.CountDownLatch(1);
132	    var certified = new java.util.concurrent.atomic.AtomicBoolean();
133	    SSLContext tls = certificate();
134	    var server = HttpsServer.create(new InetSocketAddress("localhost", 0), 0);
135	    server.setHttpsConfigurator(
136	        new HttpsConfigurator(tls) {
137	          @Override
138	          public void configure(com.sun.net.httpserver.HttpsParameters parameters) {
139	            var configuration = tls.getDefaultSSLParameters();
140	            configuration.setNeedClientAuth(true);
141	            parameters.setSSLParameters(configuration);
142	          }
143	        });
144	    var workers = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor();
145	    server.setExecutor(workers);
146	    server.createContext(
147	        "/",
148	        exchange -> {
149	          requests.incrementAndGet();
150	          received.set(exchange.getRequestBody().readAllBytes());
151	          certified.set(
152	              ((com.sun.net.httpserver.HttpsExchange) exchange)
153	                      .getSSLSession()
154	                      .getPeerCertificates()
155	                      .length
156	                  > 0);
157	          exchange.sendResponseHeaders(status, 0);
158	          try {
159	            exchange.getResponseBody().write('{');
160	            exchange.getResponseBody().flush();
161	            headers.countDown();
162	            while (true) {
163	              exchange.getResponseBody().write(' ');
164	              exchange.getResponseBody().flush();
165	              Thread.sleep(20);
166	            }
167	          } catch (java.io.IOException closed) {
168	            disconnected.countDown();
169	          } catch (InterruptedException stopped) {
170	            Thread.currentThread().interrupt();
171	          } finally {
172	            exchange.close();
173	          }
174	        });
175	    server.start();
176	    var failed = new AtomicReference<Throwable>();
177	    var interrupted = new java.util.concurrent.atomic.AtomicBoolean();
178	    var client =
179	        new GuidedRunnerClient(
180	            URI.create("https://localhost:" + server.getAddress().getPort()),
181	            tls,
182	            () -> "synthetic-controller-token",
183	            contracts);
184	    client.observeRequestBytes(owned::set);
185	    long started = System.nanoTime();
186	    Thread caller =
187	        Thread.ofVirtual()
188	            .start(
189	                () -> {
190	                  try {
191	                    client.sendSecret(
192	                        dispatch,
193	                        metadata,
194	                        secret,
195	                        defaultBound || interrupt
196	                            ? null
197	                            : java.time.Instant.now().plusMillis(1000));
198	                  } catch (Throwable refusal) {
199	                    failed.set(refusal);
200	                    interrupted.set(Thread.currentThread().isInterrupted());
201	                  }
202	                });
203	    try {
204	      assertThat(headers.await(3, java.util.concurrent.TimeUnit.SECONDS)).isTrue();
205	      if (interrupt) {
206	        caller.interrupt();
207	      }
208	      caller.join(defaultBound ? 16500 : 3000);
209	      assertThat(caller.isAlive())
210	          .as("actual production sender must finish without peer EOF")
211	          .isFalse();
212	      assertThat(failed.get())
213	          .isInstanceOf(com.citi.put.checks.studio.guided.session.GuidedSessionException.class)
214	          .hasMessage("UNKNOWN_OUTCOME");
215	      assertThat(java.time.Duration.ofNanos(System.nanoTime() - started).toMillis())
216	          .isLessThan(defaultBound ? 16000 : 3000);
217	      assertThat(requests.get()).isEqualTo(1);
218	      assertThat(certified.get()).isTrue();
219	      assertThat(new String(received.get(), StandardCharsets.UTF_8).contains(canary)).isTrue();
220	      assertThat(owned.get()).containsOnly((byte) 0);
221	      assertThat(chars).containsOnly('\0');
222	      assertThat(secret.toString()).isEqualTo("<secret>");
223	      assertThat(dispatch.toString().contains(canary)).isFalse();
224	      if (interrupt) {
225	        assertThat(interrupted.get()).isTrue();
226	      }
227	      assertThat(disconnected.await(2, java.util.concurrent.TimeUnit.SECONDS))
228	          .as("peer observes response-stream cancellation")
229	          .isTrue();
230	    } finally {
231	      caller.interrupt();
232	      server.stop(0);
233	      workers.shutdownNow();
234	      caller.join(3000);
235	      if (received.get() != null) {
236	        java.util.Arrays.fill(received.get(), (byte) 0);
237	      }
238	    }
239	  }
