241	  private SSLContext certificate() throws Exception {
242	    run(
243	        "openssl",
244	        "req",
245	        "-x509",
246	        "-newkey",
247	        "rsa:2048",
248	        "-nodes",
249	        "-keyout",
250	        temporary.resolve("key.pem").toString(),
251	        "-out",
252	        temporary.resolve("cert.pem").toString(),
253	        "-days",
254	        "1",
255	        "-subj",
256	        "/CN=localhost",
257	        "-addext",
258	        "subjectAltName=DNS:localhost");
259	    run(
260	        "openssl",
261	        "pkcs12",
262	        "-export",
263	        "-inkey",
264	        temporary.resolve("key.pem").toString(),
265	        "-in",
266	        temporary.resolve("cert.pem").toString(),
267	        "-out",
268	        temporary.resolve("fixture.p12").toString(),
269	        "-passout",
270	        "pass:fixture");
271	    var store = KeyStore.getInstance("PKCS12");
272	    try (var in = Files.newInputStream(temporary.resolve("fixture.p12"))) {
273	      store.load(in, "fixture".toCharArray());
274	    }
275	    var keys = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
276	    keys.init(store, "fixture".toCharArray());
277	    var trust = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
278	    trust.init(store);
279	    var tls = SSLContext.getInstance("TLS");
280	    tls.init(keys.getKeyManagers(), trust.getTrustManagers(), new SecureRandom());
281	    return tls;
282	  }
