284	  private void run(String... command) throws Exception {
285	    var process = new ProcessBuilder(command).redirectErrorStream(true).start();
286	    try (var in = process.getInputStream()) {
287	      in.transferTo(java.io.OutputStream.nullOutputStream());
288	    }
289	    assertThat(process.waitFor()).isZero();
290	  }
