 30	/**
 31	 * Minimal HashiCorp Vault KV v2 adapter: a bounded read, a create-only write and a metadata list.
 32	 *
 33	 * <p>Every call is test-scoped: the path template renders {@code {csiId}}, {@code {environment}},
 34	 * {@code {testId}}, {@code {kind}} and {@code {referenceName}} from a {@link VaultScope}, and the
 35	 * list prefix is that same template minus its last segment ({@link
 36	 * StudioVaultConfiguration#listPrefixTemplate}), so save, list and read cannot address different
 37	 * places.
 38	 *
 39	 * <p>Every call shares one bounded transport: the connect and request timeouts, the response-size
 40	 * cap, no redirects, and the token read from the mounted file on each call.
 41	 *
 42	 * <p><b>The write body, and its residual.</b> The value is written as {@code char[]} straight into
 43	 * a buffer this class owns, sent from that buffer without a copy, and the buffer is zero-filled on
 44	 * every exit path. What is not claimed: Jackson's recycled generator buffers and the HTTP client's
 45	 * transient buffers can still hold bytes of the body until they are reused. The same stance as
 46	 * {@code StudioReferenceResolver.Resolved} (AC-15).
 47	 *
 48	 * <p>Nothing here logs a value, a response body, or a URI that could carry one. A name may be
 49	 * logged.
 50	 */
 51	public final class HashicorpStudioVaultProvider implements StudioVaultProvider {
 52	
 53	  public static final String NAME = "hashicorp";
 54	
 55	  private static final Logger LOGGER = LoggerFactory.getLogger(HashicorpStudioVaultProvider.class);
 56	
 57	  private final StudioSecretsProperties.Vault.Hashicorp properties;
 58	  private final ObjectMapper objectMapper;
 59	  private final HttpClient client;
 60	
 61	  /**
 62	   * Handed each write buffer's backing array when the buffer is created, so a test can prove the
 63	   * array is zero after {@link #create} returns or throws. {@code null} outside tests.
 64	   */
 65	  private Consumer<byte[]> writeBufferObserver;
 66	
 67	  public HashicorpStudioVaultProvider(
 68	      StudioSecretsProperties.Vault.Hashicorp properties, ObjectMapper objectMapper) {
 69	    this.properties = properties;
 70	    this.objectMapper = objectMapper;
 71	    this.client =
 72	        HttpClient.newBuilder()
 73	            .connectTimeout(properties.connectTimeoutOrDefault())
 74	            .followRedirects(HttpClient.Redirect.NEVER)
 75	            .build();
 76	  }
 77	
 78	  @Override
 79	  public String name() {
 80	    return NAME;
 81	  }
 82	
 83	  @Override
 84	  public Optional<VaultEntry> read(ReferenceKind kind, VaultScope scope, String referenceName) {
 85	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
 86	    try {
 87	      HttpResponse<InputStream> response =
 88	          client.send(
 89	              request(dataUri(kind, scope, referenceName)).GET().build(),
 90	              HttpResponse.BodyHandlers.ofInputStream());
 91	      try (InputStream body = response.body()) {
 92	        if (response.statusCode() == 404) {
 93	          return Optional.empty();
 94	        }
 95	        if (!isSuccess(response.statusCode())) {
 96	          throw new VaultProviderUnavailableException(
 97	              "Vault refused the reference read with status " + response.statusCode());
 98	        }
 99	        byte[] bytes = readBody(body, deadline);
100	        VaultEntry entry;
101	        try {
102	          entry = parse(bytes);
103	        } finally {
104	          Arrays.fill(bytes, (byte) 0);
105	        }
106	        if (kind == ReferenceKind.SECRET && entry.allowedOrigins().isEmpty()) {
107	          // Names the reference only. Origins are not secret, but the list is not echoed either:
108	          // the entry's owner can read it, and a log line is not where it should be corrected.
109	          LOGGER.warn(
110	              "Vault entry for secret '{}' declares no valid {}; it cannot be filled on any origin",
111	              referenceName,
112	              SecretOrigins.VAULT_KEY);
113	        }
114	        return Optional.of(entry);
115	      }
116	    } catch (VaultProviderUnavailableException e) {
117	      throw e;
118	    } catch (InterruptedException e) {
119	      Thread.currentThread().interrupt();
120	      throw new VaultProviderUnavailableException("Vault reference read was interrupted", e);
121	    } catch (IOException | RuntimeException e) {
122	      throw new VaultProviderUnavailableException("Vault reference read failed", e);
123	    }
124	  }
125	
126	  /**
127	   * Create-only write: {@code POST {mount}/data/{path}} with {@code options.cas = 0}, so Vault
128	   * refuses to overwrite an existing entry.
129	   *
130	   * <p>A refused write ({@code 400}, or {@code 403} under a policy that grants {@code create} but
131	   * not {@code update}) is told apart from an outage by reading the entry's metadata: metadata
132	   * present means the name is taken ({@link SecretAlreadyExistsException}); anything else is {@link
133	   * VaultProviderUnavailableException}. That the platform Vault answers a duplicate under a
134	   * create-only policy with {@code 403} is an inference from HashiCorp's documentation, not a
135	   * verified behaviour.
136	   *
137	   * <p>{@code value} belongs to the caller, who erases it. The serialized body is erased here.
138	   */
139	  @Override
140	  public String create(VaultScope scope, String name, char[] value, List<String> origins) {
141	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
142	    ErasableBuffer buffer = new ErasableBuffer(initialCapacity(value, origins));
143	    if (writeBufferObserver != null) {
144	      writeBufferObserver.accept(buffer.backingArray());
145	    }
146	    try {
147	      writeCreateBody(buffer, value, origins);
148	      HttpResponse<InputStream> response =
149	          client.send(
150	              request(dataUri(ReferenceKind.SECRET, scope, name))
151	                  .header("Content-Type", "application/json")
152	                  .POST(buffer.publisher())
153	                  .build(),
154	              HttpResponse.BodyHandlers.ofInputStream());
155	      try (InputStream body = response.body()) {
156	        int status = response.statusCode();
157	        if (isSuccess(status)) {
158	          return writtenVersion(readBody(body, deadline));
159	        }
160	        if (status == 400 || status == 403) {
161	          if (metadataExists(scope, name, deadline)) {
162	            throw new SecretAlreadyExistsException(name);
163	          }
164	        }
165	        throw new VaultProviderUnavailableException(
166	            "Vault refused the secret write with status " + status);
167	      }
168	    } catch (VaultProviderUnavailableException | SecretAlreadyExistsException e) {
169	      throw e;
170	    } catch (InterruptedException e) {
171	      Thread.currentThread().interrupt();
172	      throw new VaultProviderUnavailableException("Vault secret write was interrupted", e);
173	    } catch (IOException | RuntimeException e) {
174	      throw new VaultProviderUnavailableException("Vault secret write failed", e);
175	    } finally {
176	      buffer.erase();
177	    }
178	  }
