180	  /**
181	   * {@code LIST {mount}/metadata/{prefix}} (sent as {@code GET ?list=true}, the documented
182	   * equivalent). A {@code 404} is an empty folder. Sub-folders and keys that fail {@link
183	   * StudioVaultProvider#isValidSecretName} are skipped: no step could reference them.
184	   */
185	  @Override
186	  public List<String> listSecretNames(VaultScope scope) {
187	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
188	    try {
189	      HttpResponse<InputStream> response =
190	          client.send(
191	              request(listUri(scope)).GET().build(), HttpResponse.BodyHandlers.ofInputStream());
192	      try (InputStream body = response.body()) {
193	        if (response.statusCode() == 404) {
194	          return List.of();
195	        }
196	        if (!isSuccess(response.statusCode())) {
197	          throw new VaultProviderUnavailableException(
198	              "Vault refused the secret list with status " + response.statusCode());
199	        }
200	        JsonNode keys = objectMapper.readTree(readBody(body, deadline)).path("data").path("keys");
201	        if (!keys.isArray()) {
202	          throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 list");
203	        }
204	        List<String> names = new ArrayList<>();
205	        for (JsonNode key : keys) {
206	          String candidate = key.isTextual() ? key.textValue() : null;
207	          if (candidate != null
208	              && !candidate.endsWith("/")
209	              && StudioVaultProvider.isValidSecretName(candidate)) {
210	            names.add(candidate);
211	          }
212	        }
213	        names.sort(null);
214	        return List.copyOf(names);
215	      }
216	    } catch (VaultProviderUnavailableException e) {
217	      throw e;
218	    } catch (InterruptedException e) {
219	      Thread.currentThread().interrupt();
220	      throw new VaultProviderUnavailableException("Vault secret list was interrupted", e);
221	    } catch (IOException | RuntimeException e) {
222	      throw new VaultProviderUnavailableException("Vault secret list failed", e);
223	    }
224	  }
