242	  private void writeCreateBody(ErasableBuffer buffer, char[] value, List<String> origins)
243	      throws IOException {
244	    try (JsonGenerator generator =
245	        objectMapper.getFactory().createGenerator(buffer, JsonEncoding.UTF8)) {
246	      generator.writeStartObject();
247	      generator.writeObjectFieldStart("options");
248	      generator.writeNumberField("cas", 0);
249	      generator.writeEndObject();
250	      generator.writeObjectFieldStart("data");
251	      generator.writeFieldName(properties.valueKeyOrDefault());
252	      generator.writeString(value, 0, value.length);
253	      generator.writeStringField(SecretOrigins.VAULT_KEY, String.join(",", origins));
254	      generator.writeEndObject();
255	      generator.writeEndObject();
256	    }
257	  }
