259	  /**
260	   * Sized so the buffer never grows: a JSON-escaped character is at most six bytes, and every
261	   * origin, the value key and the envelope are counted.
262	   */
263	  private int initialCapacity(char[] value, List<String> origins) {
264	    long capacity = 256L + 6L * value.length + 6L * properties.valueKeyOrDefault().length();
265	    for (String origin : origins) {
266	      capacity += 6L * (origin.length() + 1);
267	    }
268	    return (int) Math.min(capacity, Integer.MAX_VALUE - 8);
269	  }
270	
271	  private String writtenVersion(byte[] body) throws IOException {
272	    JsonNode version = objectMapper.readTree(body).path("data").path("version");
273	    if (!version.canConvertToInt() || version.asInt() <= 0) {
274	      throw new VaultProviderUnavailableException(
275	          "Vault returned a malformed KV v2 write response");
276	    }
277	    return Integer.toString(version.asInt());
278	  }
