286	  private byte[] readBody(InputStream body, long deadline)
287	      throws IOException, InterruptedException {
288	    byte[] bytes = readBounded(body, properties.maxResponseBytesOrDefault() + 1, deadline);
289	    if (responseBytesObserver != null) {
290	      responseBytesObserver.accept(bytes);
291	    }
292	    if (bytes.length > properties.maxResponseBytesOrDefault()) {
293	      Arrays.fill(bytes, (byte) 0);
294	      throw new VaultProviderUnavailableException("Vault returned an oversized response");
295	    }
296	    return bytes;
297	  }
