312	  private static boolean isSuccess(int status) {
313	    return status >= 200 && status < 300;
314	  }
315	
316	  private static byte[] readBounded(InputStream body, int limit, long deadline)
317	      throws IOException, InterruptedException {
318	    FutureTask<byte[]> read =
319	        new FutureTask<>(
320	            () -> {
321	              try {
322	                return body.readNBytes(limit);
323	              } catch (IOException e) {
324	                throw new VaultBodyReadException(e);
325	              }
326	            });
327	    Thread reader = Thread.ofVirtual().name("studio-vault-body-reader").start(read);
328	    long remaining = deadline - System.nanoTime();
329	    if (remaining <= 0) {
330	      read.cancel(true);
331	      body.close();
332	      throw new VaultProviderUnavailableException("Vault response exceeded the request deadline");
333	    }
334	    try {
335	      return read.get(remaining, TimeUnit.NANOSECONDS);
336	    } catch (TimeoutException e) {
337	      read.cancel(true);
338	      body.close();
339	      throw new VaultProviderUnavailableException(
340	          "Vault response exceeded the request deadline", e);
341	    } catch (ExecutionException e) {
342	      if (e.getCause() instanceof VaultBodyReadException bodyRead) {
343	        throw bodyRead.ioCause();
344	      }
345	      throw new VaultProviderUnavailableException("Vault response could not be read", e);
346	    } finally {
347	      if (!read.isDone()) {
348	        reader.interrupt();
349	      }
350	    }
351	  }
