353	  private static final class VaultBodyReadException extends RuntimeException {
354	    private static final long serialVersionUID = 1L;
355	
356	    private VaultBodyReadException(IOException cause) {
357	      super(cause);
358	    }
359	
360	    private IOException ioCause() {
361	      return (IOException) getCause();
362	    }
363	  }
