365	  private VaultEntry parse(byte[] body) throws IOException {
366	    char[] value = null;
367	    int version = 0;
368	    List<String> origins = List.of();
369	    var path = new java.util.ArrayDeque<String>();
370	    try (var parser = objectMapper.getFactory().createParser(body)) {
371	      com.fasterxml.jackson.core.JsonToken token;
372	      String field = null;
373	      while ((token = parser.nextToken()) != null) {
374	        if (token == com.fasterxml.jackson.core.JsonToken.FIELD_NAME) {
375	          field = parser.currentName();
376	        } else {
377	          if (token == com.fasterxml.jackson.core.JsonToken.START_OBJECT
378	              || token == com.fasterxml.jackson.core.JsonToken.START_ARRAY) {
379	            path.addLast(field == null ? "$" : field);
380	            field = null;
381	          } else {
382	            if (token.isStructEnd()) {
383	              path.removeLast();
384	              field = null;
385	            } else {
386	              if (List.copyOf(path).equals(List.of("$", "data", "data"))) {
387	                if (properties.valueKeyOrDefault().equals(field)) {
388	                  if (token != com.fasterxml.jackson.core.JsonToken.VALUE_STRING || value != null) {
389	                    throw new VaultProviderUnavailableException(
390	                        "Vault returned a malformed KV v2 response");
391	                  }
392	                  value =
393	                      java.util.Arrays.copyOfRange(
394	                          parser.getTextCharacters(),
395	                          parser.getTextOffset(),
396	                          parser.getTextOffset() + parser.getTextLength());
397	                } else {
398	                  if (SecretOrigins.VAULT_KEY.equals(field)
399	                      && token == com.fasterxml.jackson.core.JsonToken.VALUE_STRING) {
400	                    origins = SecretOrigins.parse(parser.getText());
401	                  }
402	                }
403	              } else {
404	                if (List.copyOf(path).equals(List.of("$", "data", "metadata"))
405	                    && "version".equals(field)
406	                    && token == com.fasterxml.jackson.core.JsonToken.VALUE_NUMBER_INT) {
407	                  version = parser.getIntValue();
408	                }
409	              }
410	            }
411	          }
412	        }
413	      }
414	      if (value == null || version <= 0) {
415	        throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 response");
416	      }
417	      return new VaultEntry(value, Integer.toString(version), origins);
418	    } catch (IOException | RuntimeException failure) {
419	      if (value != null) {
420	        java.util.Arrays.fill(value, '\0');
421	      }
422	      throw failure;
423	    }
424	  }
