426	  /**
427	   * The entry's {@value SecretOrigins#VAULT_KEY}, normalized. Absent, non-text or malformed all
428	   * mean no origin: the secret then cannot be filled, which is the fail-closed reading. Nothing
429	   * about a malformed list is thrown or logged here, because nothing here knows which reference it
430	   * was; {@link #read} says so by name.
431	   */
432	  private static List<String> allowedOrigins(JsonNode node) {
433	    return node.isTextual() ? SecretOrigins.parse(node.textValue()) : List.of();
434	  }
