445	  private URI listUri(VaultScope scope) {
446	    String prefix = StudioVaultConfiguration.listPrefixTemplate(properties.pathTemplateOrDefault());
447	    return URI.create(
448	        vaultUri("metadata", render(prefix, ReferenceKind.SECRET, scope, null)) + "?list=true");
