451	  private static String render(
452	      String template, ReferenceKind kind, VaultScope scope, String referenceName) {
453	    String path =
454	        template
455	            .replace("{csiId}", segment(scope.csiId()))
456	            .replace("{environment}", segment(scope.environment()))
457	            .replace("{testId}", segment(scope.testId()))
458	            .replace("{kind}", kind == ReferenceKind.SECRET ? "secrets" : "variables");
459	    return referenceName == null ? path : path.replace("{referenceName}", segment(referenceName));
460	  }
