462	  private URI vaultUri(String api, String path) {
463	    String base = properties.address().replaceAll("/+$", "");
464	    return URI.create(
465	        base + "/v1/" + segment(properties.mountOrDefault()) + "/" + api + "/" + path);
466	  }
