491	  /**
492	   * A body buffer that can be erased. It exposes its backing array to the request publisher rather
493	   * than copying it out, and when it must grow it zero-fills the array it leaves behind, so at no
494	   * point does an unerased copy of the body exist that this class cannot reach.
495	   */
496	  private static final class ErasableBuffer extends ByteArrayOutputStream {
497	
498	    private ErasableBuffer(int capacity) {
499	      super(capacity);
500	    }
501	
502	    @Override
503	    public synchronized void write(int b) {
504	      ensureErasingCapacity(1);
505	      super.write(b);
506	    }
507	
508	    @Override
509	    public synchronized void write(byte[] bytes, int offset, int length) {
510	      ensureErasingCapacity(length);
511	      super.write(bytes, offset, length);
512	    }
513	
514	    private void ensureErasingCapacity(int extra) {
515	      if (count + extra <= buf.length) {
516	        return;
517	      }
518	      byte[] grown = Arrays.copyOf(buf, Math.max(buf.length * 2, count + extra));
519	      Arrays.fill(buf, (byte) 0);
520	      buf = grown;
521	    }
522	
523	    private synchronized byte[] backingArray() {
524	      return buf;
525	    }
526	
527	    private synchronized HttpRequest.BodyPublisher publisher() {
528	      return HttpRequest.BodyPublishers.ofByteArray(buf, 0, count);
529	    }
530	
531	    private synchronized void erase() {
532	      Arrays.fill(buf, (byte) 0);
533	      count = 0;
534	    }
535	  }
