    39	  private JsonNode secretInput(JsonNode context, JsonNode proposal) {
    40	    JsonNode value = proposal.path("operation").path("value");
    41	    if (!value.path("kind").asText().equals("secretRef")) {
    42	      return null;
    43	    }
    44	    JsonNode input =
    45	        com.citi.put.checks.studio.guided.publication.GuidedPlanBuilder.unique(
    46	            context.path("authoredInputs").path("inputs"),
    47	            "inputId",
    48	            value.path("sourceInputId").asText());
    49	    require(
    50	        input.path("kind").asText().equals("secretRef")
    51	            && input.path("sourceStepId").equals(proposal.path("coordinate").path("stepId"))
    52	            && input.path("intendedSlot").asText().equals("fill.value")
    53	            && proposal.path("target").path("kind").asText().equals("passwordControl"),
    54	        "REFERENCE_MISMATCH",
    55	        422);
    56	    return input;
    57	  }
