    59	  private void preflight(String id, JsonNode input) {
    60	    if (input == null) {
    61	      return;
    62	    }
    63	    require(references != null, "SECRET_UNAVAILABLE", 404);
    64	    JsonNode session = sessions.secretSession(id), scope = session.path("scope");
    65	    try {
    66	      references.preflight(
    67	          scope.path("csiId").asText(),
    68	          scope.path("environmentId").asText(),
    69	          java.util.UUID.fromString(session.path("testId").asText()),
    70	          scope.path("principalId").asText(),
    71	          new com.citi.put.checks.studio.dispatch.ReferenceDeclarations(
    72	              java.util.List.of(), java.util.List.of(input.path("secretId").asText())));
    73	    } catch (SecretUseNotAuthorizedException failure) {
    74	      throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
    75	          "SECRET_USE_REVOKED", 409);
    76	    } catch (UnknownReferenceException failure) {
    77	      throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
    78	          "SECRET_UNAVAILABLE", 404);
    79	    } catch (VaultProviderUnavailableException failure) {
    80	      throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
    81	          "VAULT_UNAVAILABLE", 503);
    82	    }
    83	  }
