    87	    noTransaction();
    88	    ObjectNode intent = sessions.prepareAssignment(controller, id, key, workerId);
    89	    JsonNode receipt = runner.send("assign", intent, key);
    90	    sessions.acknowledgeAssignment(controller, id, receipt);
    91	    return receipt;
