    99	  public JsonNode observe(
   100	      Authentication controller, String id, long fence, String key, JsonNode request) {
   101	    noTransaction();
   102	    JsonNode committed = sessions.beginObservationRefresh(controller, id, fence, key, request);
   103	    if (committed != null) {
   104	      return committed;
   105	    }
   106	    JsonNode response;
   107	    try {
   108	      response = runner.send("observe", request, key);
   109	    } catch (RuntimeException failure) {
   110	      JsonNode recovered =
   111	          sessions.committedObservationRefresh(controller, id, fence, key, request, null);
   112	      if (recovered != null) {
   113	        return recovered;
   114	      }
   115	      throw failure;
   116	    }
   117	    return sessions.committedObservationRefresh(controller, id, fence, key, request, response);
   118	  }
