   120	  public JsonNode prepareAndAdmit(
   121	      Authentication controller, String id, long fence, String key, JsonNode proposal) {
   122	    noTransaction();
   123	    JsonNode existing = sessions.existingAdmission(controller, id, fence, key, proposal);
   124	    if (existing != null) {
   125	      return existing;
   126	    }
   127	    ObjectNode context = sessions.runnerContext(controller, id, fence);
   128	    preflight(id, secretInput(context, proposal));
   129	    runner.send("context", context);
   130	    ObjectNode request = materialization.identity(context);
   131	    request.set("proposal", proposal);
   132	    request.put("requestDigest", GuidedContracts.hash(proposal));
   133	    request.set("expiresAt", context.path("leaseExpiresAt"));
   134	    JsonNode proof = runner.send("prepare", request);
   135	    sessions.storePreparation(controller, id, fence, proposal, proof);
   136	    return sessions.admit(controller, id, fence, key, proposal);
   137	  }
