   139	  public JsonNode dispatch(
   140	      Authentication controller, String id, long fence, String key, JsonNode request) {
   141	    noTransaction();
   142	    var consumed = sessions.consume(controller, id, fence, key, request);
   143	    if (consumed instanceof GuidedSessionService.AlreadyConsumed prior) {
   144	      return prior.ledger();
   145	    }
   146	    var won = (GuidedSessionService.WonConsumption) consumed;
   147	    ObjectNode payload = materialization.identity(won.context());
   148	    payload.set("proposal", won.proposal());
   149	    payload.set("ledger", won.ledger());
   150	    payload.set("preparationId", won.ledger().path("preparationId"));
   151	    var edges = payload.putArray("consumerEdges");
   152	    for (JsonNode edge : won.context().path("consumerEdges")) {
   153	      if (edge.path("consumerAdmissionId")
   154	          .equals(won.ledger().path("admission").path("admissionId"))) {
   155	        edges.add(edge);
   156	      }
   157	    }
   158	    try {
   159	      JsonNode input = secretInput(won.context(), won.proposal());
   160	      if (input == null) {
   161	        runner.send(
   162	            "dispatch",
   163	            payload,
   164	            java.util.UUID.randomUUID().toString(),
   165	            java.time.Instant.parse(won.context().path("expiresAt").asText()));
   166	      } else {
   167	        require(references != null, "SECRET_UNAVAILABLE", 404);
   168	        JsonNode session = sessions.secretSession(id), scope = session.path("scope");
   169	        String secretId = input.path("secretId").asText();
   170	        try (var resolved =
   171	            references.resolve(
   172	                scope.path("csiId").asText(),
   173	                scope.path("environmentId").asText(),
   174	                java.util.UUID.fromString(session.path("testId").asText()),
   175	                scope.path("principalId").asText(),
   176	                new com.citi.put.checks.studio.dispatch.ReferenceDeclarations(
   177	                    java.util.List.of(), java.util.List.of(secretId)))) {
   178	          ObjectNode metadata =
   179	              new GuidedContracts()
   180	                  .object()
   181	                  .put("secretId", secretId)
   182	                  .put("versionId", resolved.secretVersions().get(secretId));
   183	          var origins = metadata.putArray("allowedOrigins");
   184	          resolved
   185	              .secretOrigins()
   186	              .getOrDefault(secretId, java.util.List.of())
   187	              .forEach(origins::add);
   188	          sessions.recordSecretDecision(
   189	              id,
   190	              won.ledger(),
   191	              secretId,
   192	              resolved.secretVersions().get(secretId),
   193	              com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome.RESOLVED);
   194	          String origin = won.proposal().path("executionEvidence").path("origin").asText();
   195	          if (origins.isEmpty()
   196	              || origins.size() > 16
   197	              || metadata.path("versionId").asText().length() > 256
   198	              || !resolved
   199	                  .secretOrigins()
   200	                  .getOrDefault(secretId, java.util.List.of())
   201	                  .contains(origin)) {
   202	            sessions.refuseResolvedSecret(id, won.ledger());
   203	            throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
   204	                "ORIGIN_NOT_ALLOWED", 403);
   205	          }
   206	          runner.sendSecret(
   207	              payload,
   208	              metadata,
   209	              resolved.secretValues().get(secretId),
   210	              java.time.Instant.parse(session.path("expiresAt").asText()));
   211	        } catch (SecretUseRevokedException failure) {
   212	          sessions.recordSecretDecision(
   213	              id,
   214	              won.ledger(),
   215	              secretId,
   216	              null,
   217	              com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome.REVOKED);
   218	          throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
   219	              "SECRET_USE_REVOKED", 409);
   220	        } catch (StudioReferenceResolver.ReferenceUnavailableException failure) {
   221	          sessions.recordSecretDecision(
   222	              id,
   223	              won.ledger(),
   224	              secretId,
   225	              null,
   226	              com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome
   227	                  .UNAVAILABLE);
   228	          throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
   229	              "SECRET_UNAVAILABLE", 404);
   230	        } catch (VaultProviderUnavailableException failure) {
   231	          sessions.recordSecretDecision(
   232	              id,
   233	              won.ledger(),
   234	              secretId,
   235	              null,
   236	              com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome
   237	                  .VAULT_UNAVAILABLE);
   238	          throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
   239	              "VAULT_UNAVAILABLE", 503);
   240	        } catch (SecretTooLongException failure) {
   241	          sessions.recordSecretDecision(
   242	              id,
   243	              won.ledger(),
   244	              secretId,
   245	              null,
   246	              com.citi.put.checks.studio.secrets.SecretUseAuditRecorder.ResolutionOutcome
   247	                  .UNAVAILABLE,
   248	              "SECRET_TOO_LONG");
   249	          throw new com.citi.put.checks.studio.guided.session.GuidedSessionException(
   250	              "SECRET_TOO_LONG", 422);
   251	        }
   252	      }
   253	    } catch (RuntimeException failure) {
   254	      sessions.lostAcknowledgment(id, won.ledger().path("admission").path("admissionId").asText());
   255	      throw failure;
   256	    }
   257	    // HTTP200 does not substitute for an owner-authenticated committed callback.
   258	    sessions.lostAcknowledgment(id, won.ledger().path("admission").path("admissionId").asText());
   259	    // The owner-authenticated callback is commit authority; response is only transport ack.
   260	    return won.ledger();
   261	  }
