   263	  public void stop(ObjectNode lastContext, String reason) {
   264	    noTransaction();
   265	    ObjectNode stop;
   266	    if (lastContext.has("assignmentId")) {
   267	      stop = new GuidedContracts().object().put("schemaVersion", 3).put("kind", "assignment");
