 84	  public Optional<VaultEntry> read(ReferenceKind kind, VaultScope scope, String referenceName) {
 85	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
 86	    try {
 87	      HttpResponse<InputStream> response =
 88	          client.send(
 89	              request(dataUri(kind, scope, referenceName)).GET().build(),
 90	              HttpResponse.BodyHandlers.ofInputStream());
 91	      try (InputStream body = response.body()) {
 92	        if (response.statusCode() == 404) {
 93	          return Optional.empty();
 94	        }
 95	        if (!isSuccess(response.statusCode())) {
 96	          throw new VaultProviderUnavailableException(
 97	              "Vault refused the reference read with status " + response.statusCode());
 98	        }
 99	        byte[] bytes = readBody(body, deadline);
100	        VaultEntry entry;
