107	          // Names the reference only. Origins are not secret, but the list is not echoed either:
108	          // the entry's owner can read it, and a log line is not where it should be corrected.
109	          LOGGER.warn(
110	              "Vault entry for secret '{}' declares no valid {}; it cannot be filled on any origin",
111	              referenceName,
