126	  /**
127	   * Create-only write: {@code POST {mount}/data/{path}} with {@code options.cas = 0}, so Vault
128	   * refuses to overwrite an existing entry.
129	   *
130	   * <p>A refused write ({@code 400}, or {@code 403} under a policy that grants {@code create} but
131	   * not {@code update}) is told apart from an outage by reading the entry's metadata: metadata
132	   * present means the name is taken ({@link SecretAlreadyExistsException}); anything else is {@link
133	   * VaultProviderUnavailableException}. That the platform Vault answers a duplicate under a
134	   * create-only policy with {@code 403} is an inference from HashiCorp's documentation, not a
135	   * verified behaviour.
136	   *
137	   * <p>{@code value} belongs to the caller, who erases it. The serialized body is erased here.
138	   */
139	  @Override
140	  public String create(VaultScope scope, String name, char[] value, List<String> origins) {
141	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
142	    ErasableBuffer buffer = new ErasableBuffer(initialCapacity(value, origins));
143	    if (writeBufferObserver != null) {
144	      writeBufferObserver.accept(buffer.backingArray());
145	    }
146	    try {
147	      writeCreateBody(buffer, value, origins);
148	      HttpResponse<InputStream> response =
149	          client.send(
150	              request(dataUri(ReferenceKind.SECRET, scope, name))
151	                  .header("Content-Type", "application/json")
152	                  .POST(buffer.publisher())
153	                  .build(),
154	              HttpResponse.BodyHandlers.ofInputStream());
155	      try (InputStream body = response.body()) {
156	        int status = response.statusCode();
157	        if (isSuccess(status)) {
158	          return writtenVersion(readBody(body, deadline));
159	        }
160	        if (status == 400 || status == 403) {
161	          if (metadataExists(scope, name, deadline)) {
162	            throw new SecretAlreadyExistsException(name);
163	          }
164	        }
165	        throw new VaultProviderUnavailableException(
166	            "Vault refused the secret write with status " + status);
167	      }
168	    } catch (VaultProviderUnavailableException | SecretAlreadyExistsException e) {
169	      throw e;
170	    } catch (InterruptedException e) {
171	      Thread.currentThread().interrupt();
172	      throw new VaultProviderUnavailableException("Vault secret write was interrupted", e);
173	    } catch (IOException | RuntimeException e) {
174	      throw new VaultProviderUnavailableException("Vault secret write failed", e);
175	    } finally {
176	      buffer.erase();
177	    }
178	  }
179	
180	  /**
181	   * {@code LIST {mount}/metadata/{prefix}} (sent as {@code GET ?list=true}, the documented
182	   * equivalent). A {@code 404} is an empty folder. Sub-folders and keys that fail {@link
183	   * StudioVaultProvider#isValidSecretName} are skipped: no step could reference them.
184	   */
185	  @Override
186	  public List<String> listSecretNames(VaultScope scope) {
187	    long deadline = System.nanoTime() + properties.requestTimeoutOrDefault().toNanos();
188	    try {
189	      HttpResponse<InputStream> response =
190	          client.send(
191	              request(listUri(scope)).GET().build(), HttpResponse.BodyHandlers.ofInputStream());
192	      try (InputStream body = response.body()) {
193	        if (response.statusCode() == 404) {
194	          return List.of();
195	        }
196	        if (!isSuccess(response.statusCode())) {
197	          throw new VaultProviderUnavailableException(
198	              "Vault refused the secret list with status " + response.statusCode());
199	        }
200	        JsonNode keys = objectMapper.readTree(readBody(body, deadline)).path("data").path("keys");
201	        if (!keys.isArray()) {
202	          throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 list");
203	        }
204	        List<String> names = new ArrayList<>();
205	        for (JsonNode key : keys) {
206	          String candidate = key.isTextual() ? key.textValue() : null;
207	          if (candidate != null
208	              && !candidate.endsWith("/")
209	              && StudioVaultProvider.isValidSecretName(candidate)) {
210	            names.add(candidate);
211	          }
212	        }
213	        names.sort(null);
214	        return List.copyOf(names);
215	      }
216	    } catch (VaultProviderUnavailableException e) {
217	      throw e;
218	    } catch (InterruptedException e) {
219	      Thread.currentThread().interrupt();
220	      throw new VaultProviderUnavailableException("Vault secret list was interrupted", e);
221	    } catch (IOException | RuntimeException e) {
222	      throw new VaultProviderUnavailableException("Vault secret list failed", e);
223	    }
224	  }
225	
226	  /** Whether the entry's metadata exists: the one question a refused create-only write asks. */
227	  private boolean metadataExists(VaultScope scope, String name, long deadline)
228	      throws IOException, InterruptedException {
229	    HttpResponse<InputStream> response =
230	        client.send(
231	            request(metadataUri(scope, name)).GET().build(),
232	            HttpResponse.BodyHandlers.ofInputStream());
233	    try (InputStream body = response.body()) {
234	      if (response.statusCode() != 200) {
235	        return false;
236	      }
237	      readBody(body, deadline);
238	      return true;
239	    }
240	  }
241	
242	  private void writeCreateBody(ErasableBuffer buffer, char[] value, List<String> origins)
243	      throws IOException {
244	    try (JsonGenerator generator =
245	        objectMapper.getFactory().createGenerator(buffer, JsonEncoding.UTF8)) {
246	      generator.writeStartObject();
247	      generator.writeObjectFieldStart("options");
248	      generator.writeNumberField("cas", 0);
249	      generator.writeEndObject();
250	      generator.writeObjectFieldStart("data");
251	      generator.writeFieldName(properties.valueKeyOrDefault());
252	      generator.writeString(value, 0, value.length);
253	      generator.writeStringField(SecretOrigins.VAULT_KEY, String.join(",", origins));
254	      generator.writeEndObject();
255	      generator.writeEndObject();
256	    }
257	  }
258	
259	  /**
260	   * Sized so the buffer never grows: a JSON-escaped character is at most six bytes, and every
261	   * origin, the value key and the envelope are counted.
262	   */
263	  private int initialCapacity(char[] value, List<String> origins) {
264	    long capacity = 256L + 6L * value.length + 6L * properties.valueKeyOrDefault().length();
265	    for (String origin : origins) {
266	      capacity += 6L * (origin.length() + 1);
267	    }
268	    return (int) Math.min(capacity, Integer.MAX_VALUE - 8);
269	  }
270	
271	  private String writtenVersion(byte[] body) throws IOException {
272	    JsonNode version = objectMapper.readTree(body).path("data").path("version");
273	    if (!version.canConvertToInt() || version.asInt() <= 0) {
274	      throw new VaultProviderUnavailableException(
275	          "Vault returned a malformed KV v2 write response");
276	    }
277	    return Integer.toString(version.asInt());
278	  }
279	
280	  private java.util.function.Consumer<byte[]> responseBytesObserver;
281	
282	  void observeResponseBytes(java.util.function.Consumer<byte[]> observer) {
283	    this.responseBytesObserver = observer;
284	  }
285	
286	  private byte[] readBody(InputStream body, long deadline)
287	      throws IOException, InterruptedException {
288	    byte[] bytes = readBounded(body, properties.maxResponseBytesOrDefault() + 1, deadline);
289	    if (responseBytesObserver != null) {
290	      responseBytesObserver.accept(bytes);
291	    }
292	    if (bytes.length > properties.maxResponseBytesOrDefault()) {
293	      Arrays.fill(bytes, (byte) 0);
294	      throw new VaultProviderUnavailableException("Vault returned an oversized response");
295	    }
296	    return bytes;
297	  }
298	
299	  private HttpRequest.Builder request(URI uri) throws IOException {
300	    HttpRequest.Builder request =
301	        HttpRequest.newBuilder(uri)
302	            .timeout(properties.requestTimeoutOrDefault())
303	            .header("Accept", "application/json")
304	            .header("X-Vault-Request", "true")
305	            .header("X-Vault-Token", readToken());
306	    if (properties.namespace() != null && !properties.namespace().isBlank()) {
307	      request.header("X-Vault-Namespace", properties.namespace().trim());
308	    }
309	    return request;
310	  }
311	
312	  private static boolean isSuccess(int status) {
313	    return status >= 200 && status < 300;
314	  }
315	
316	  private static byte[] readBounded(InputStream body, int limit, long deadline)
317	      throws IOException, InterruptedException {
318	    FutureTask<byte[]> read =
319	        new FutureTask<>(
320	            () -> {
321	              try {
322	                return body.readNBytes(limit);
323	              } catch (IOException e) {
324	                throw new VaultBodyReadException(e);
325	              }
326	            });
327	    Thread reader = Thread.ofVirtual().name("studio-vault-body-reader").start(read);
328	    long remaining = deadline - System.nanoTime();
329	    if (remaining <= 0) {
330	      read.cancel(true);
331	      body.close();
332	      throw new VaultProviderUnavailableException("Vault response exceeded the request deadline");
333	    }
334	    try {
335	      return read.get(remaining, TimeUnit.NANOSECONDS);
336	    } catch (TimeoutException e) {
337	      read.cancel(true);
338	      body.close();
339	      throw new VaultProviderUnavailableException(
340	          "Vault response exceeded the request deadline", e);
341	    } catch (ExecutionException e) {
342	      if (e.getCause() instanceof VaultBodyReadException bodyRead) {
343	        throw bodyRead.ioCause();
344	      }
345	      throw new VaultProviderUnavailableException("Vault response could not be read", e);
346	    } finally {
347	      if (!read.isDone()) {
348	        reader.interrupt();
349	      }
350	    }
351	  }
352	
353	  private static final class VaultBodyReadException extends RuntimeException {
354	    private static final long serialVersionUID = 1L;
355	
356	    private VaultBodyReadException(IOException cause) {
357	      super(cause);
358	    }
359	
360	    private IOException ioCause() {
361	      return (IOException) getCause();
362	    }
363	  }
364	
365	  private VaultEntry parse(byte[] body) throws IOException {
366	    char[] value = null;
367	    int version = 0;
368	    List<String> origins = List.of();
369	    var path = new java.util.ArrayDeque<String>();
370	    try (var parser = objectMapper.getFactory().createParser(body)) {
371	      com.fasterxml.jackson.core.JsonToken token;
372	      String field = null;
373	      while ((token = parser.nextToken()) != null) {
374	        if (token == com.fasterxml.jackson.core.JsonToken.FIELD_NAME) {
375	          field = parser.currentName();
376	        } else {
377	          if (token == com.fasterxml.jackson.core.JsonToken.START_OBJECT
378	              || token == com.fasterxml.jackson.core.JsonToken.START_ARRAY) {
379	            path.addLast(field == null ? "$" : field);
380	            field = null;
381	          } else {
382	            if (token.isStructEnd()) {
383	              path.removeLast();
384	              field = null;
385	            } else {
386	              if (List.copyOf(path).equals(List.of("$", "data", "data"))) {
387	                if (properties.valueKeyOrDefault().equals(field)) {
388	                  if (token != com.fasterxml.jackson.core.JsonToken.VALUE_STRING || value != null) {
389	                    throw new VaultProviderUnavailableException(
390	                        "Vault returned a malformed KV v2 response");
391	                  }
392	                  value =
393	                      java.util.Arrays.copyOfRange(
394	                          parser.getTextCharacters(),
395	                          parser.getTextOffset(),
396	                          parser.getTextOffset() + parser.getTextLength());
397	                } else {
398	                  if (SecretOrigins.VAULT_KEY.equals(field)
399	                      && token == com.fasterxml.jackson.core.JsonToken.VALUE_STRING) {
400	                    origins = SecretOrigins.parse(parser.getText());
401	                  }
402	                }
403	              } else {
404	                if (List.copyOf(path).equals(List.of("$", "data", "metadata"))
405	                    && "version".equals(field)
406	                    && token == com.fasterxml.jackson.core.JsonToken.VALUE_NUMBER_INT) {
407	                  version = parser.getIntValue();
408	                }
409	              }
410	            }
411	          }
412	        }
413	      }
414	      if (value == null || version <= 0) {
415	        throw new VaultProviderUnavailableException("Vault returned a malformed KV v2 response");
416	      }
417	      return new VaultEntry(value, Integer.toString(version), origins);
418	    } catch (IOException | RuntimeException failure) {
419	      if (value != null) {
420	        java.util.Arrays.fill(value, '\0');
421	      }
422	      throw failure;
423	    }
424	  }
425	
426	  /**
427	   * The entry's {@value SecretOrigins#VAULT_KEY}, normalized. Absent, non-text or malformed all
428	   * mean no origin: the secret then cannot be filled, which is the fail-closed reading. Nothing
429	   * about a malformed list is thrown or logged here, because nothing here knows which reference it
430	   * was; {@link #read} says so by name.
431	   */
432	  private static List<String> allowedOrigins(JsonNode node) {
433	    return node.isTextual() ? SecretOrigins.parse(node.textValue()) : List.of();
434	  }
435	
436	  private URI dataUri(ReferenceKind kind, VaultScope scope, String referenceName) {
437	    return vaultUri("data", render(properties.pathTemplateOrDefault(), kind, scope, referenceName));
438	  }
439	
440	  private URI metadataUri(VaultScope scope, String name) {
441	    return vaultUri(
442	        "metadata", render(properties.pathTemplateOrDefault(), ReferenceKind.SECRET, scope, name));
443	  }
444	
445	  private URI listUri(VaultScope scope) {
446	    String prefix = StudioVaultConfiguration.listPrefixTemplate(properties.pathTemplateOrDefault());
447	    return URI.create(
448	        vaultUri("metadata", render(prefix, ReferenceKind.SECRET, scope, null)) + "?list=true");
449	  }
450	
451	  private static String render(
452	      String template, ReferenceKind kind, VaultScope scope, String referenceName) {
453	    String path =
454	        template
455	            .replace("{csiId}", segment(scope.csiId()))
456	            .replace("{environment}", segment(scope.environment()))
457	            .replace("{testId}", segment(scope.testId()))
458	            .replace("{kind}", kind == ReferenceKind.SECRET ? "secrets" : "variables");
459	    return referenceName == null ? path : path.replace("{referenceName}", segment(referenceName));
460	  }
461	
462	  private URI vaultUri(String api, String path) {
463	    String base = properties.address().replaceAll("/+$", "");
464	    return URI.create(
465	        base + "/v1/" + segment(properties.mountOrDefault()) + "/" + api + "/" + path);
466	  }
467	
468	  private String readToken() throws IOException {
469	    String token = Files.readString(Path.of(properties.tokenFile())).trim();
470	    if (token.isEmpty()) {
471	      throw new IOException("empty Vault token file");
472	    }
473	    return token;
474	  }
475	
476	  private static String segment(String value) {
477	    if (value == null || value.isBlank()) {
478	      throw new VaultProviderUnavailableException("Vault reference coordinates are incomplete");
479	    }
480	    if (value.contains("/") || value.contains("\\") || ".".equals(value) || "..".equals(value)) {
481	      throw new VaultProviderUnavailableException("Vault reference coordinates are not path-safe");
482	    }
483	    return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
484	  }
485	
486	  /** Test hook: see {@link #writeBufferObserver}. */
487	  void observeWriteBuffers(Consumer<byte[]> observer) {
488	    this.writeBufferObserver = observer;
489	  }
490	
491	  /**
492	   * A body buffer that can be erased. It exposes its backing array to the request publisher rather
493	   * than copying it out, and when it must grow it zero-fills the array it leaves behind, so at no
494	   * point does an unerased copy of the body exist that this class cannot reach.
495	   */
496	  private static final class ErasableBuffer extends ByteArrayOutputStream {
497	
498	    private ErasableBuffer(int capacity) {
499	      super(capacity);
500	    }
501	
502	    @Override
503	    public synchronized void write(int b) {
504	      ensureErasingCapacity(1);
505	      super.write(b);
506	    }
507	
508	    @Override
509	    public synchronized void write(byte[] bytes, int offset, int length) {
510	      ensureErasingCapacity(length);
511	      super.write(bytes, offset, length);
512	    }
513	
514	    private void ensureErasingCapacity(int extra) {
515	      if (count + extra <= buf.length) {
516	        return;
517	      }
518	      byte[] grown = Arrays.copyOf(buf, Math.max(buf.length * 2, count + extra));
519	      Arrays.fill(buf, (byte) 0);
520	      buf = grown;
521	    }
522	
523	    private synchronized byte[] backingArray() {
524	      return buf;
525	    }
526	
527	    private synchronized HttpRequest.BodyPublisher publisher() {
528	      return HttpRequest.BodyPublishers.ofByteArray(buf, 0, count);
529	    }
530	
531	    private synchronized void erase() {
532	      Arrays.fill(buf, (byte) 0);
533	      count = 0;
534	    }
535	  }
536	}

